#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    std::vector<int> datos;
    int cantidad_entrada{0};
    std::cin >> cantidad_entrada;
    for (int entrada{0}; entrada < cantidad_entrada; ++entrada) {
        int dato{0};
        std::cin >> dato;
        datos.push_back(dato);
    }
    if (datos.empty()) {
        std::cout << "Sin datos";
    } else {
        auto ordenados = datos;
        std::sort(ordenados.begin(), ordenados.end());
        auto centro = ordenados.size() / 2;
        double mediana = 0.0;
        if (ordenados.size() % 2 != 0) {
            mediana = ordenados.at(centro);
        } else {
            mediana = (static_cast<double>(ordenados.at(centro - 1)) + ordenados.at(centro)) / 2.0;
        }
        std::cout << "Mediana: " << mediana;
    }
    return 0;
}

